#!/usr/bin/env python3
"""Verify the self-signed TLS certificate for the internal development server."""

import os
import ssl
import sys
from datetime import datetime, timezone

CERT_PATH = "/app/ssl/server.crt"


def main() -> int:
    if not os.path.isfile(CERT_PATH):
        print(f"ERROR: certificate file not found: {CERT_PATH}")
        return 1

    try:
        cert = ssl._ssl._test_decode_cert(CERT_PATH)
    except Exception as exc:
        print(f"ERROR: certificate could not be loaded: {exc}")
        return 1

    common_name = None
    organization = None
    for rdn in cert.get("subject", ()):
        for attr, value in rdn:
            if attr == "commonName":
                common_name = value
            elif attr == "organizationName":
                organization = value

    not_after = cert.get("notAfter")
    if not common_name or not not_after:
        print("ERROR: certificate is missing the Common Name or expiration date")
        return 1

    expiry = datetime.fromtimestamp(
        ssl.cert_time_to_seconds(not_after), tz=timezone.utc
    )

    print(f"Certificate file: {CERT_PATH}")
    print(f"Common Name: {common_name}")
    print(f"Organization: {organization}")
    print(f"Expiration date: {expiry:%Y-%m-%d}")

    if expiry <= datetime.now(timezone.utc):
        print("ERROR: certificate has expired")
        return 1

    print("Certificate verification successful")
    return 0


if __name__ == "__main__":
    sys.exit(main())

